// docs.ts — CRUD over the `docs` table. Plain organizational documents
// (notes, playbook references, and "living" docs whose body is periodically
// regenerated by livingDocs.ts). No model calls happen here.
import { db } from "@/db";
import { docs } from "@/db/schema";
import { desc, eq } from "drizzle-orm";

export type CreateDocInput = {
  entityId?: string | null;
  title: string;
  body: string;
  docType?: string;
  tags?: string[];
  isLiving?: boolean;
};

export async function createDoc(input: CreateDocInput) {
  const [row] = await db
    .insert(docs)
    .values({
      entityId: input.entityId ?? null,
      title: input.title,
      body: input.body,
      docType: input.docType ?? "note",
      tags: input.tags ?? [],
      isLiving: input.isLiving ?? false,
    })
    .returning();
  return row;
}

export async function listDocs(opts: { entityId?: string; isLiving?: boolean } = {}) {
  const rows = await db.select().from(docs).orderBy(desc(docs.updatedAt));
  return rows.filter(
    (r) =>
      (opts.entityId === undefined || r.entityId === opts.entityId) &&
      (opts.isLiving === undefined || r.isLiving === opts.isLiving),
  );
}

export async function getDoc(id: string) {
  const [row] = await db.select().from(docs).where(eq(docs.id, id)).limit(1);
  return row;
}

export async function updateDocBody(id: string, body: string, markRegenerated = false) {
  const [row] = await db
    .update(docs)
    .set({
      body,
      updatedAt: new Date(),
      ...(markRegenerated ? { lastRegeneratedAt: new Date() } : {}),
    })
    .where(eq(docs.id, id))
    .returning();
  return row;
}
